def max_run(s):
    if not s:
        return 0

    max_len = 1
    current_len = 1

    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            current_len += 1
            max_len = max(max_len, current_len)
        else:
            current_len = 1

    return max_len
